_smt.a.6", "pl-2_smt.a", "pl-2_smt.a.12", "pl-2_smt.e", "pl-2_smt.a.9", "pl-2_gdn", "pl-2_smt.a.8"], "CM-5(4)": ["cm-5.4_gdn", "cm-5.4_smt"], "AC-2": ["ac-2_smt.h.3", "ac-2_smt", "ac-2_gdn", "ac-2_smt.d.3", "ac-2_smt.d.1", "ac-2_smt.i", "ac-2_smt.c", "ac-2_smt.i.1", "ac-2_smt.a", "ac-2_smt.e", "ac-2_smt.d.2"], "CA-1": ["ca-1_smt.a.1", "ca-1_smt.b", "ca-1_smt", "ca-1_smt.c", "ca-1_smt.a.2", "ca-1_smt.a.1.a", "ca-1_gdn", "ca-1_smt.a.1.b"], "CA-3": ["ca-3_smt.a", "ca-3_gdn"], "AT-3": ["at-3_smt", "at-3_smt.a.1", "at-3_gdn"], "AC-6(1)": ["ac-6.1_gdn", "ac-6.1_smt.b", "ac-6.1_smt.a", "ac-6.1_smt"]}, "n_docs": 62}, "allowed_controls": ["CA-6", "CA-6"], "control_widen_tier": 1, "primary_control": "CA-6", "winner_control": "CA-6", "selector_raw": {"answer_text": "", "evidence_spans": [{"source_id": "ca-6_gdn", "span_text": ""}, {"source_id": "ca-6_smt.c", "span_text": ""}, {"source_id": "ca-6_smt.c.1", "span_text": ""}, {"source_id": "ca-6_smt.c.2", "span_text": ""}, {"source_id": "ca-6_smt.a", "span_text": ""}, {"source_id": "ca-6_smt.b", "span_text": ""}, {"source_id": "ca-6_smt.e", "span_text": ""}], "status": "OK", "odp_required_list": []}, "doc_filter_mode_used": "prefer_smt_keep_params", "primary_first_applied": false, "hierarchy_added_ids": [], "fallback_used": false, "fallback_reason": "", "secondary_fallback_used": false, "secondary_fallback_reason": "", "secondary_fallback_selected_id": "", "secondary_fallback_candidates_checked": [], "counts": {"retrieved_docs": 62, "docs_for_gen": 13, "evidence_spans": 7}}, "validity_check": {"is_pass": false, "errors": ["ValidityCheckException:NameError("name 'verify_span' is not defined")"]}, "verification": {"question_id": "19", "is_pass": false, "error_tags": ["MissedDocIds:['ca-6_smt.d']"], "metrics": {"control_precision": 1.0, "control_recall": 1.0, "control_f1": 1.0, "doc_precision": 0.8571428571428571, "doc_recall": 0.8571428571428571, "doc_f1": 0.8571428571428571, "precision": 1.0, "recall": 1.0, "f1": 1.0, "verbatim_strict_pass_rate": 1.0, "verbatim_normalized_pass_rate": 1.0}}, "selected_source_ids": ["ca-6_gdn", "ca-6_smt.c", "ca-6_smt.c.1", "ca-6_smt.c.2", "ca-6_smt.a", "ca-6_smt.b", "ca-6_smt.e"], "verifier_ran": true, "verifier_pass": false, "verifier_errors": ["MissedDocIds:['ca-6_smt.d']"], "verifier_metrics": {"control_precision": 1.0, "control_recall": 1.0, "control_f1": 1.0, "doc_precision": 0.8571428571428571, "doc_recall": 0.8571428571428571, "doc_f1": 0.8571428571428571, "precision": 1.0, "recall": 1.0, "f1": 1.0, "verbatim_strict_pass_rate": 1.0, "verbatim_normalized_pass_rate": 1.0}, "answer_text_with_citation": "Authorizations are official management decisions by senior officials to authorize operation of systems, authorize the use of common controls for inheritance by organizational systems, and explicitly accept the risk to organizational operations and assets, individuals, other organizations, and the Nation based on the implementation of agreed-upon controls. Authorizing officials provide budgetary oversight for organizational systems and common controls or assume responsibility for the mission and business functions supported by those systems or common controls. The authorization process is a federal responsibility, and therefore, authorizing officials must be federal employees. Authorizing officials are both responsible and accountable for security and privacy risks associated with the operation and use of organizational systems. Nonfederal organizations may have similar processes to authorize systems and senior officials that assume the authorization role and associated responsibilities.

Authorizing officials issue ongoing authorizations of systems based on evidence produced from implemented continuous monitoring programs. Robust continuous monitoring programs reduce the need for separate reauthorization processes. Through the employment of comprehensive continuous monitoring processes, the information contained in authorization packages (i.e., security and privacy plans, assessment reports, and plans of action and milestones) is updated on an ongoing basis. This provides authorizing officials, common control providers, and system owners with an up-to-date status of the security and privacy posture of their systems, controls, and operating environments. To reduce the cost of reauthorization, authorizing officials can leverage the results of continuous monitoring processes to the maximum extent possible as the basis for rendering reauthorization decisions.

Ensure that the authorizing official for the system, before commencing operations:

Accepts the use of common controls inherited by the system; and

Authorizes the system to operate;

Assign a senior official as the authorizing official for the system;

Assign a senior official as the authorizing official for common controls available for inheritance by organizational systems;

Update the authorizations {{ insert: param, ca-06_odp }}.

Citations: ca-6_gdn, ca-6_smt.c, ca-6_smt.c.1, ca-6_smt.c.2, ca-6_smt.a, ca-6_smt.b, ca-6_smt.e (NIST SP 800-53 Rev. 5)", "contract_mode": "provably_extractive"}

answer:
Assign a senior official as the authorizing official for the system;
Ensure that the authorizing official for common controls authorizes the use of those controls for inheritance by organizational systems;
Authorizes the system to operate;
Accepts the use of common controls inherited by the system; and
Update the authorizations {{ insert: param, ca-06_odp }}. [NIST SP 800-53 Rev.5: CA-6]

